using System;using System.IO;using ScoreModern.RecoveredFragments;
class InputChordPitchProof{
 static int Main(string[] a){try{byte[] ds=File.ReadAllBytes(a[0]),tokens=File.ReadAllBytes(a[1]),bounds=File.ReadAllBytes(a[2]),after=File.ReadAllBytes(a[3]),ads=File.ReadAllBytes(a[4]);int count=BitConverter.ToInt16(tokens,0);float[] values=new float[count];Buffer.BlockCopy(tokens,2,values,0,count*4);var r=InputPitchRecords.Compile(values,BitConverter.ToSingle(ds,0x8780),0,BitConverter.ToSingle(bounds,0),BitConverter.ToSingle(bounds,4),true);if(r.Records.Count!=BitConverter.ToInt16(ads,0x8798)||r.Events!=BitConverter.ToInt16(ads,0x879c)||r.NoteIndices.Count!=BitConverter.ToInt16(ads,0x8788))throw new Exception("Counts");int words=0;for(int i=0;i<r.Records.Count;i++)for(int p=0;p<15;p++){if(BitConverter.ToInt32(BitConverter.GetBytes(r.Records[i][p]),0)!=BitConverter.ToInt32(after,i*60+p*4))throw new Exception("Record "+i+" P"+(p+1)+": "+r.Records[i][p]+" != "+BitConverter.ToSingle(after,i*60+p*4));words++;}for(int i=0;i<r.NoteIndices.Count;i++)if(r.NoteIndices[i]!=BitConverter.ToInt16(after,0x2b5c+i*2)||r.ForcedStems[i]!=BitConverter.ToInt16(after,0x2a30+i*2))throw new Exception("Map "+i);Console.WriteLine("PASS "+words+" original chord pitch words, event/note counts and maps");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
